struct RuntimeDeleter{void operator()(JSRuntime* p)const noexcept{if(p)JS_FreeRuntime(p);}};
struct ContextDeleter{void operator()(JSContext* p)const noexcept{if(p)JS_FreeContext(p);}};
using Runtime=std::unique_ptr<JSRuntime,RuntimeDeleter>;
using Context=std::unique_ptr<JSContext,ContextDeleter>;
struct InterruptState{const CancellationToken* cancellation=nullptr;std::uint64_t remaining=0;bool cancelled=false;bool exhausted=false;};
int interrupt(JSRuntime*,void* opaque){auto& s=*static_cast<InterruptState*>(opaque);if(s.cancellation&&s.cancellation->cancelled()){s.cancelled=true;return 1;}if(s.remaining==0){s.exhausted=true;return 1;}--s.remaining;return 0;}
JSValue to_js(JSContext* ctx,const Value& value){return std::visit([&](const auto& item)->JSValue{using T=std::decay_t<decltype(item)>;if constexpr(std::is_same_v<T,std::int64_t>)return JS_NewInt64(ctx,item);else if constexpr(std::is_same_v<T,double>)return JS_NewFloat64(ctx,item);else if constexpr(std::is_same_v<T,bool>)return JS_NewBool(ctx,item);else return JS_NewStringLen(ctx,item.data(),item.size());},value);}
std::string text(JSContext* ctx,JSValueConst value){const char* raw=JS_ToCString(ctx,value);if(!raw)return {};std::string result(raw);JS_FreeCString(ctx,raw);return result;}
std::string exception(JSContext* ctx){const auto value=JS_GetException(ctx);auto result=text(ctx,value);JS_FreeValue(ctx,value);return result.empty()?"JavaScript exception.":result;}
EvaluationResult failure(EvaluationStatus status,DiagnosticCode code,std::string message){return {status,{},{{code,std::move(message),{}, {}}}};}
EvaluationResult interrupted(const InterruptState& state){if(state.cancelled)return failure(EvaluationStatus::cancelled,DiagnosticCode::cancelled,"Script evaluation was cancelled.");return failure(EvaluationStatus::budget_exceeded,DiagnosticCode::instruction_budget_exceeded,"Script instruction budget was exceeded.");}
bool set(JSContext* ctx,JSValueConst object,const std::string& name,JSValue value){return JS_SetPropertyStr(ctx,object,name.c_str(),value)>=0;}
std::optional<Value> scalar(JSContext* ctx,JSValueConst value){if(JS_IsBool(value))return Value{JS_ToBool(ctx,value)!=0};if(JS_VALUE_GET_TAG(value)==JS_TAG_INT){std::int64_t result=0;if(JS_ToInt64(ctx,&result,value)<0)return {};return Value{result};}if(JS_IsNumber(value)){double result=0;if(JS_ToFloat64(ctx,&result,value)<0)return {};return Value{result};}if(JS_IsString(value))return Value{text(ctx,value)};return {};}
ScriptResult script_failure(EvaluationStatus status,DiagnosticCode code,std::string message){return {status,{},{{code,std::move(message),{}, {}}},{}};}
ScriptResult script_interrupted(const InterruptState& state){if(state.cancelled)return script_failure(EvaluationStatus::cancelled,DiagnosticCode::cancelled,"Script execution was cancelled.");return script_failure(EvaluationStatus::budget_exceeded,DiagnosticCode::instruction_budget_exceeded,"Script instruction budget was exceeded.");}
struct ScriptContextState{GeometryScriptHost* host=nullptr;std::string console;std::size_t log_entries=0;};
ScriptContextState& script_state(JSContext* ctx){return *static_cast<ScriptContextState*>(JS_GetContextOpaque(ctx));}
GeometryScriptHost& host(JSContext* ctx){return *script_state(ctx).host;}
std::string string_arg(JSContext* ctx,JSValueConst value){const auto result=text(ctx,value);if(result.empty()&&!JS_IsString(value))throw std::invalid_argument("Expected a string argument.");return result;}
std::uint64_t integer_arg(JSContext* ctx,JSValueConst value){std::int64_t result=0;if(JS_ToInt64(ctx,&result,value)<0||result<0)throw std::invalid_argument("Expected a non-negative integer argument.");return static_cast<std::uint64_t>(result);}
double number_arg(JSContext* ctx,JSValueConst value){double result=0;if(JS_ToFloat64(ctx,&result,value)<0)throw std::invalid_argument("Expected a numeric argument.");return result;}
phoenix::LabelId label_arg(JSContext* ctx,JSValueConst value){const auto raw=integer_arg(ctx,value);if(raw>static_cast<std::uint64_t>(INT32_MAX))throw std::invalid_argument("Label identifier is outside the supported integer range.");return phoenix::LabelId{static_cast<std::int32_t>(raw)};}
JSValue native_builder_add_vertex(JSContext*,JSValueConst,int,JSValueConst*);
JSValue native_builder_add_face(JSContext*,JSValueConst,int,JSValueConst*);
JSValue handle_object(JSContext* ctx,const char* kind,std::uint64_t token){auto result=JS_NewObject(ctx);if(JS_IsException(result))return result;if(!set(ctx,result,"__phoenixKind",JS_NewString(ctx,kind))||!set(ctx,result,"token",JS_NewInt64(ctx,static_cast<std::int64_t>(token)))){JS_FreeValue(ctx,result);return JS_EXCEPTION;}JS_FreezeObject(ctx,result);return result;}
JSValue builder_object(JSContext* ctx,std::uint64_t token){auto result=JS_NewObject(ctx);set(ctx,result,"__phoenixKind",JS_NewString(ctx,"geometry"));set(ctx,result,"token",JS_NewInt64(ctx,static_cast<std::int64_t>(token)));set(ctx,result,"add_vertex",JS_NewCFunction(ctx,native_builder_add_vertex,"add_vertex",3));set(ctx,result,"add_face",JS_NewCFunction(ctx,native_builder_add_face,"add_face",3));set(ctx,result,"error",JS_NULL);JS_FreezeObject(ctx,result);return result;}
std::uint64_t handle_arg(JSContext* ctx,JSValueConst value){if(!JS_IsObject(value))throw std::invalid_argument("Expected a Phoenix geometry handle.");auto token=JS_GetPropertyStr(ctx,value,"token");const auto result=integer_arg(ctx,token);JS_FreeValue(ctx,token);return result;}
JSValue native_create_geometry(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=1)throw std::invalid_argument("createGeometry(output) expects one argument.");return handle_object(ctx,"geometry",host(ctx).create_geometry(string_arg(ctx,argv[0])));}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue native_build_mesh(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=1)throw std::invalid_argument("build_mesh(output) expects the explicit geometry output name.");return builder_object(ctx,host(ctx).create_geometry(string_arg(ctx,argv[0])));}catch(const std::exception&e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue native_clone_geometry(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=2)throw std::invalid_argument("cloneGeometry(input, output) expects two arguments.");return handle_object(ctx,"geometry",host(ctx).clone_geometry(string_arg(ctx,argv[0]),string_arg(ctx,argv[1])));}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue native_vertex_count(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=1)throw std::invalid_argument("vertexCount(geometry) expects one argument.");return JS_NewInt64(ctx,static_cast<std::int64_t>(host(ctx).geometry_vertex_count(handle_arg(ctx,argv[0]))));}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue native_face_count(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=1)throw std::invalid_argument("faceCount(geometry) expects one argument.");return JS_NewInt64(ctx,static_cast<std::int64_t>(host(ctx).geometry_face_count(handle_arg(ctx,argv[0]))));}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue point_object(JSContext* ctx,phoenix::Point3d point){auto result=JS_NewObject(ctx);if(JS_IsException(result))return result;if(!set(ctx,result,"x",JS_NewFloat64(ctx,point.x))||!set(ctx,result,"y",JS_NewFloat64(ctx,point.y))||!set(ctx,result,"z",JS_NewFloat64(ctx,point.z))){JS_FreeValue(ctx,result);return JS_EXCEPTION;}JS_FreezeObject(ctx,result);return result;}
JSValue native_vertex(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=2)throw std::invalid_argument("vertex(geometry, index) expects two arguments.");return point_object(ctx,host(ctx).geometry_vertex(handle_arg(ctx,argv[0]),static_cast<std::size_t>(integer_arg(ctx,argv[1]))));}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue label_array(JSContext* ctx,const std::vector<phoenix::LabelId>& values){auto result=JS_NewArray(ctx);for(std::size_t i=0;i<values.size();++i)JS_SetPropertyUint32(ctx,result,static_cast<std::uint32_t>(i),JS_NewInt64(ctx,values[i].value()));JS_FreezeObject(ctx,result);return result;}
JSValue index_array(JSContext* ctx,const std::vector<std::uint64_t>& values){auto result=JS_NewArray(ctx);for(std::size_t i=0;i<values.size();++i)JS_SetPropertyUint32(ctx,result,static_cast<std::uint32_t>(i),JS_NewInt64(ctx,static_cast<std::int64_t>(values[i])));JS_FreezeObject(ctx,result);return result;}
JSValue handle_array(JSContext* ctx,const char* kind,const std::vector<std::uint64_t>& values){auto result=JS_NewArray(ctx);for(std::size_t i=0;i<values.size();++i)JS_SetPropertyUint32(ctx,result,static_cast<std::uint32_t>(i),handle_object(ctx,kind,values[i]));JS_FreezeObject(ctx,result);return result;}
JSValue optional_handle(JSContext* ctx,const char* kind,const std::optional<std::uint64_t>& value){return value?handle_object(ctx,kind,*value):JS_NULL;}
JSValue native_inspect_geometry(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=1)throw std::invalid_argument("inspectGeometry(mesh) expects one argument.");const auto v=host(ctx).inspect_geometry(handle_arg(ctx,argv[0]));auto r=JS_NewObject(ctx);set(ctx,r,"empty",JS_NewBool(ctx,v.empty));set(ctx,r,"size_of_vertices",JS_NewInt64(ctx,v.vertices));set(ctx,r,"size_of_halfedges",JS_NewInt64(ctx,v.halfedges));set(ctx,r,"size_of_facets",JS_NewInt64(ctx,v.faces));set(ctx,r,"size_of_border_halfedges",JS_NewInt64(ctx,v.border_halfedges));set(ctx,r,"size_of_border_edges",JS_NewInt64(ctx,v.border_edges));set(ctx,r,"is_closed",JS_NewBool(ctx,v.closed));set(ctx,r,"is_pure_bivalent",JS_NewBool(ctx,v.pure_bivalent));set(ctx,r,"is_pure_trivalent",JS_NewBool(ctx,v.pure_trivalent));set(ctx,r,"is_pure_triangle",JS_NewBool(ctx,v.pure_triangle));set(ctx,r,"is_pure_quad",JS_NewBool(ctx,v.pure_quad));JS_FreezeObject(ctx,r);return r;}catch(const std::exception&e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue native_inspect_element(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=1)throw std::invalid_argument("inspect(element) expects one argument.");const auto v=host(ctx).inspect_element(handle_arg(ctx,argv[0]));const char* kind=v.kind==ScriptOutputKind::vertices?"vertices":v.kind==ScriptOutputKind::faces?"faces":"halfedges";auto r=JS_NewObject(ctx);set(ctx,r,"kind",JS_NewString(ctx,kind));set(ctx,r,"index",JS_NewInt64(ctx,v.stable_id));set(ctx,r,"degree",JS_NewInt64(ctx,v.degree));set(ctx,r,"is_bivalent",JS_NewBool(ctx,v.bivalent));set(ctx,r,"is_trivalent",JS_NewBool(ctx,v.trivalent));set(ctx,r,"is_triangle",JS_NewBool(ctx,v.triangle));set(ctx,r,"is_quad",JS_NewBool(ctx,v.quad));set(ctx,r,"is_border",JS_NewBool(ctx,v.border));set(ctx,r,"is_border_edge",JS_NewBool(ctx,v.border_edge));if(v.point){set(ctx,r,"point",point_object(ctx,*v.point));set(ctx,r,"x",JS_NewFloat64(ctx,v.point->x));set(ctx,r,"y",JS_NewFloat64(ctx,v.point->y));set(ctx,r,"z",JS_NewFloat64(ctx,v.point->z));}if(v.label)set(ctx,r,"label",JS_NewInt64(ctx,v.label->value()));set(ctx,r,"halfedge",optional_handle(ctx,"halfedges",v.halfedge));set(ctx,r,"opposite",optional_handle(ctx,"halfedges",v.opposite));set(ctx,r,"next",optional_handle(ctx,"halfedges",v.next));set(ctx,r,"prev",optional_handle(ctx,"halfedges",v.prev));set(ctx,r,"next_on_vertex",optional_handle(ctx,"halfedges",v.next_on_vertex));set(ctx,r,"prev_on_vertex",optional_handle(ctx,"halfedges",v.prev_on_vertex));set(ctx,r,"source",optional_handle(ctx,"vertices",v.source));set(ctx,r,"target",optional_handle(ctx,"vertices",v.target));set(ctx,r,"vertex",optional_handle(ctx,"vertices",v.target));set(ctx,r,"facet",optional_handle(ctx,"faces",v.face));set(ctx,r,"incident_halfedges",handle_array(ctx,"halfedges",v.incident_halfedges));JS_FreezeObject(ctx,r);return r;}catch(const std::exception&e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
JSValue native_face(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=2)throw std::invalid_argument("face(geometry, index) expects two arguments.");const auto face=host(ctx).geometry_face(handle_arg(ctx,argv[0]),static_cast<std::size_t>(integer_arg(ctx,argv[1])));auto result=JS_NewObject(ctx);if(!set(ctx,result,"vertices",index_array(ctx,face.vertices))||!set(ctx,result,"label",JS_NewInt64(ctx,face.label.value()))||!set(ctx,result,"directedEdgeLabels",label_array(ctx,face.directed_edge_labels))){JS_FreeValue(ctx,result);return JS_EXCEPTION;}JS_FreezeObject(ctx,result);return result;}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
