JSValue native_add_vertex(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc!=4)throw std::invalid_argument("addVertex(geometry, x, y, z) expects four arguments.");return JS_NewInt64(ctx,static_cast<std::int64_t>(host(ctx).add_vertex(handle_arg(ctx,argv[0]),{number_arg(ctx,argv[1]),number_arg(ctx,argv[2]),number_arg(ctx,argv[3])})));}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
std::vector<std::uint64_t> integer_array(JSContext* ctx,JSValueConst value){if(!JS_IsArray(value))throw std::invalid_argument("Expected an array.");std::int64_t count=0;if(JS_GetLength(ctx,value,&count)<0)throw std::invalid_argument("Could not read array length.");std::vector<std::uint64_t> result;for(std::int64_t i=0;i<count;++i){auto item=JS_GetPropertyUint32(ctx,value,static_cast<std::uint32_t>(i));result.push_back(integer_arg(ctx,item));JS_FreeValue(ctx,item);}return result;}
JSValue native_add_face(JSContext* ctx,JSValueConst,int argc,JSValueConst* argv){try{if(argc<2||argc>4)throw std::invalid_argument("addFace(geometry, vertices[, label[, edgeLabels]]) expects two to four arguments.");ScriptFace face;face.vertices=integer_array(ctx,argv[1]);if(argc>=3&&!JS_IsUndefined(argv[2]))face.label=label_arg(ctx,argv[2]);if(argc==4){if(!JS_IsArray(argv[3]))throw std::invalid_argument("Directed edge labels must be an array.");std::int64_t count=0;JS_GetLength(ctx,argv[3],&count);for(std::int64_t i=0;i<count;++i){auto item=JS_GetPropertyUint32(ctx,argv[3],static_cast<std::uint32_t>(i));face.directed_edge_labels.push_back(label_arg(ctx,item));JS_FreeValue(ctx,item);}}host(ctx).add_face(handle_arg(ctx,argv[0]),face);return JS_UNDEFINED;}catch(const std::exception& e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
