JSValue native_builder_add_face(JSContext* ctx,JSValueConst self,int argc,JSValueConst* argv){try{if(argc<1||argc>3)throw std::invalid_argument("builder.add_face(vertices[, label[, edgeLabels]]) expects one to three arguments.");ScriptFace face;face.vertices=integer_array(ctx,argv[0]);if(argc>=2&&!JS_IsUndefined(argv[1]))face.label=label_arg(ctx,argv[1]);if(argc==3){if(!JS_IsArray(argv[2]))throw std::invalid_argument("Directed edge labels must be an array.");std::int64_t count=0;JS_GetLength(ctx,argv[2],&count);for(std::int64_t i=0;i<count;++i){auto item=JS_GetPropertyUint32(ctx,argv[2],static_cast<std::uint32_t>(i));face.directed_edge_labels.push_back(label_arg(ctx,item));JS_FreeValue(ctx,item);}}host(ctx).add_face(handle_arg(ctx,self),face);return JS_UNDEFINED;}catch(const std::exception&e){return JS_ThrowTypeError(ctx,"%s",e.what());}}
